/**
 * TASK: Complete CargoVan, a subclass of the provided RoadVehicle.
 * RoadVehicle and CityCar are provided -- do not edit them.
 *
 * Every vehicle knows its plate and purchase price, but each KIND of vehicle
 * costs a different amount to run, so annualCost is abstract.
 *
 * A CargoVan also carries a payload rating in tonnes, and its cost model is:
 *
 *   annualCost(km) = purchase price * 0.15 + km * 0.22 + payload * 300
 *
 * For example a van bought for 40000 that hauls 2 tonnes and drives 10000 km
 * a year costs 6000 + 2200 + 600 = 8800.
 *
 * CargoVan must also override summary() so that it returns "VAN " followed by
 * whatever the inherited summary() would have produced -- use super.
 */
abstract class RoadVehicle {
    private final String plate;
    private final double purchasePrice;

    protected RoadVehicle(String plate, double purchasePrice) {
        this.plate = plate;
        this.purchasePrice = purchasePrice;
    }

    public String getPlate() {
        return plate;
    }

    public double getPurchasePrice() {
        return purchasePrice;
    }

    /** Cost of running this vehicle for one year over the given distance. */
    public abstract double annualCost(int kilometres);

    public String summary() {
        return plate + " costs " + Math.round(annualCost(10000)) + " per year";
    }
}

class CityCar extends RoadVehicle {
    public CityCar(String plate, double purchasePrice) {
        super(plate, purchasePrice);
    }

    @Override
    public double annualCost(int kilometres) {
        return getPurchasePrice() * 0.10 + kilometres * 0.12;
    }
}

public class CargoVan extends RoadVehicle {

    private final double payloadTonnes;

    public CargoVan(String plate, double purchasePrice, double payloadTonnes) {
        // TODO: hand the plate and price to the superclass, then store the payload
        super("", 0);
        this.payloadTonnes = payloadTonnes;
    }

    public double getPayloadTonnes() {
        return payloadTonnes;
    }

    @Override
    public double annualCost(int kilometres) {
        // TODO: price * 0.15 + kilometres * 0.22 + payload * 300
        return 0.0;
    }

    @Override
    public String summary() {
        // TODO: "VAN " in front of the inherited summary
        return "";
    }
}

