public class CargoVanTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object round2(java.util.function.Supplier<Double> body) {
        try {
            return Math.round(body.get() * 100.0) / 100.0;
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        CargoVan van = new CargoVan("VN-1", 40000, 2);

        check("getPlate comes from the superclass", "VN-1", safe(van::getPlate));
        check("getPurchasePrice comes from the superclass", 40000.0, round2(van::getPurchasePrice));
        check("getPayloadTonnes", 2.0, round2(van::getPayloadTonnes));
        check("annualCost(10000)", 8800.0, round2(() -> van.annualCost(10000)));
        check("annualCost(0)", 6600.0, round2(() -> van.annualCost(0)));
        check("summary uses super", "VAN VN-1 costs 8800 per year", safe(van::summary));

        RoadVehicle asVehicle = van;
        check("polymorphic call picks the van cost model", 8800.0,
                round2(() -> asVehicle.annualCost(10000)));

        RoadVehicle[] fleet = {new CityCar("CC-9", 20000), new CargoVan("VN-2", 30000, 1)};
        check("mixed fleet total", 10200.0,
                round2(() -> fleet[0].annualCost(10000) + fleet[1].annualCost(10000)));
        check("a CityCar summary is untouched", "CC-9 costs 3200 per year",
                safe(fleet[0]::summary));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

